#!/usr/bin/env python3
"""
Safely test the current process/system limit for open file handles.

This script opens temporary files until open() fails (typically with EMFILE:
"Too many open files") or until --max is reached. It keeps handles open so the
limit is actually exercised, then closes and removes all temp files on exit.

Examples:
  python3 test_open_file_limit.py
  python3 test_open_file_limit.py --max 10000 --report-every 500
  python3 test_open_file_limit.py --dir /tmp/ofd-test --keep-files
"""

from __future__ import annotations

import argparse
import errno
import os
import platform
import resource
import signal
import sys
import tempfile
from pathlib import Path
from typing import BinaryIO


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Test how many file handles this process can open."
    )
    parser.add_argument(
        "--max",
        type=int,
        default=1_000_000,
        help="Safety cap: stop after this many files even if no OS error occurs. Default: 1,000,000",
    )
    parser.add_argument(
        "--dir",
        type=Path,
        default=None,
        help="Directory for temporary files. Default: create a temp directory under the OS temp path.",
    )
    parser.add_argument(
        "--report-every",
        type=int,
        default=1000,
        help="Print progress every N opened files. Default: 1000",
    )
    parser.add_argument(
        "--keep-files",
        action="store_true",
        help="Do not remove the temp files/directory after the test. Handles are still closed.",
    )
    parser.add_argument(
        "--raise-soft-limit",
        action="store_true",
        help="Try to raise RLIMIT_NOFILE soft limit to the hard limit before testing (Unix only).",
    )
    return parser.parse_args()


def nofile_limits() -> tuple[int | str, int | str] | None:
    try:
        soft, hard = resource.getrlimit(resource.RLIMIT_NOFILE)
        return soft, hard
    except Exception:
        return None


def maybe_raise_soft_limit() -> None:
    limits = nofile_limits()
    if not limits:
        print("RLIMIT_NOFILE unavailable on this platform; cannot raise soft limit.")
        return

    soft, hard = limits
    if soft == hard:
        print(f"Soft file limit already equals hard limit: {soft}")
        return

    try:
        resource.setrlimit(resource.RLIMIT_NOFILE, (hard, hard))
        print(f"Raised RLIMIT_NOFILE soft limit from {soft} to {hard}")
    except (PermissionError, ValueError, OSError) as exc:
        print(f"Could not raise soft limit from {soft} to {hard}: {exc}")


def main() -> int:
    args = parse_args()

    if args.max < 1:
        print("--max must be at least 1", file=sys.stderr)
        return 2
    if args.report_every < 1:
        print("--report-every must be at least 1", file=sys.stderr)
        return 2

    if args.raise_soft_limit:
        maybe_raise_soft_limit()

    limits = nofile_limits()
    print(f"Platform: {platform.platform()}")
    if limits:
        print(f"RLIMIT_NOFILE soft={limits[0]} hard={limits[1]}")
    else:
        print("RLIMIT_NOFILE: unavailable")
    print(f"Safety cap (--max): {args.max}")

    created_tempdir = False
    if args.dir is None:
        test_dir = Path(tempfile.mkdtemp(prefix="open-file-limit-"))
        created_tempdir = True
    else:
        test_dir = args.dir
        test_dir.mkdir(parents=True, exist_ok=True)

    print(f"Temp directory: {test_dir}")

    handles: list[BinaryIO] = []
    paths: list[Path] = []
    interrupted = False

    def handle_signal(signum: int, _frame: object) -> None:
        nonlocal interrupted
        interrupted = True
        print(f"\nReceived signal {signum}; stopping and cleaning up...", file=sys.stderr)

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    failure: OSError | None = None

    try:
        for i in range(args.max):
            if interrupted:
                break

            path = test_dir / f"handle-{i:09d}.tmp"
            try:
                # Use low-level flags first so we can force close on wrapping errors.
                fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_RDWR, 0o600)
                try:
                    handle = os.fdopen(fd, "w+b", buffering=0)
                except Exception:
                    os.close(fd)
                    raise
            except OSError as exc:
                failure = exc
                break

            handles.append(handle)
            paths.append(path)

            count = i + 1
            if count % args.report_every == 0:
                print(f"Opened {count} files...")

        print("\nResult")
        print("------")
        print(f"Opened file handles: {len(handles)}")

        if failure is None:
            if interrupted:
                print("Stopped because the test was interrupted.")
            else:
                print("Stopped because --max was reached before the OS refused more handles.")
        else:
            name = errno.errorcode.get(failure.errno, "UNKNOWN")
            print(f"Failure errno: {failure.errno} ({name})")
            print(f"Failure message: {failure}")
            if failure.errno == errno.EMFILE:
                print("Interpretation: this process hit its open-file descriptor limit.")
            elif failure.errno == errno.ENFILE:
                print("Interpretation: the system-wide open-file table limit was reached.")
            elif failure.errno == errno.ENOSPC:
                print("Interpretation: storage/inode space ran out before the file-handle limit.")

        return 0

    finally:
        for handle in handles:
            try:
                handle.close()
            except OSError:
                pass

        if args.keep_files:
            print(f"Kept {len(paths)} temp files in: {test_dir}")
        else:
            removed = 0
            for path in paths:
                try:
                    path.unlink()
                    removed += 1
                except FileNotFoundError:
                    pass
                except OSError as exc:
                    print(f"Warning: could not remove {path}: {exc}", file=sys.stderr)

            if created_tempdir:
                try:
                    test_dir.rmdir()
                except OSError as exc:
                    print(f"Warning: could not remove temp dir {test_dir}: {exc}", file=sys.stderr)

            print(f"Cleaned up {removed} temp files.")


if __name__ == "__main__":
    raise SystemExit(main())

